using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    //  CalculateTotal – happy-path via [DataRow]
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero unit price")]
    [DataRow(10.00, 0, 0.10, 0.00, DisplayName = "Zero quantity")]
    [DataRow(99.99, 1, 1.0, 199.98, DisplayName = "Maximum tax rate (100%)")]
    [DataRow(99.99, 1, 0.0, 99.99, DisplayName = "Minimum tax rate (0%)")]
    public void CalculateTotal_ReturnsExpectedResult(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    //  CalculateTotal – invalid inputs via [DynamicData]
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> InvalidCalculateTotalInputs =>
    [
        [/* unitPrice */ -1m,  /* qty */ 1,  /* tax */ 0.1m, "Negative unit price"],
        [/* unitPrice */  5m,  /* qty */ -1, /* tax */ 0.1m, "Negative quantity"],
        [/* unitPrice */  5m,  /* qty */ 1,  /* tax */ -0.01m, "Tax rate below zero"],
        [/* unitPrice */  5m,  /* qty */ 1,  /* tax */ 1.01m, "Tax rate above one"],
    ];

    [TestMethod]
    [DynamicData(nameof(InvalidCalculateTotalInputs))]
    public void CalculateTotal_WithInvalidInput_ThrowsArgumentOutOfRangeException(
        decimal unitPrice, int quantity, decimal taxRate, string scenario)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(unitPrice, quantity, taxRate),
            $"Scenario: {scenario}");
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – happy-path via [DataRow]
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "0% discount")]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% discount")]
    [DataRow(100.00, 50.0, 50.00, DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% discount")]
    [DataRow(59.99, 15.0, 50.9915, DisplayName = "Fractional result")]
    [DataRow(0.00, 25.0, 0.00, DisplayName = "Zero price with discount")]
    public void ApplyDiscount_ReturnsExpectedResult(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – boundary / invalid via [DynamicData] method source
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> InvalidDiscountInputs()
    {
        yield return [200m, -1m, "Discount below zero"];
        yield return [200m, 100.01m, "Discount above 100"];
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountInputs), DynamicDataSourceType.Method)]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRangeException(
        decimal price, decimal discountPercent, string scenario)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent),
            $"Scenario: {scenario}");
    }

    // ───────────────────────────────────────────────
    //  CalculateTotal + ApplyDiscount combined via [DynamicData]
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> EndToEndScenarios =>
    [
        [/* unitPrice */ 50m, /* qty */ 2, /* tax */ 0.10m, /* discount */ 20m, /* expected */ 88.00m,
            "2 × $50 + 10% tax, then 20% off"],
        [/* unitPrice */ 100m, /* qty */ 1, /* tax */ 0.0m, /* discount */ 0m, /* expected */ 100.00m,
            "No tax, no discount"],
        [/* unitPrice */ 9.99m, /* qty */ 3, /* tax */ 0.07m, /* discount */ 50m, /* expected */ 16.03m,
            "Budget items, 7% tax, half off"],
    ];

    [TestMethod]
    [DynamicData(nameof(EndToEndScenarios))]
    public void CalculateTotal_ThenApplyDiscount_ReturnsExpectedFinalPrice(
        decimal unitPrice, int quantity, decimal taxRate,
        decimal discountPercent, decimal expected, string scenario)
    {
        var total = _calculator.CalculateTotal(unitPrice, quantity, taxRate);
        var result = _calculator.ApplyDiscount(total, discountPercent);

        Assert.AreEqual(expected, result, $"Scenario: {scenario}");
    }
}

